std::vector<std::vector<cg3::Point2d>> result;
cg3::cgal::internal::DT dt;
for (const auto& p : points) {
    dt.insert(cg3::cgal::internal::Point_2(p.x(), p.y()));
}
cg3::cgal::internal::VD vd(dt);
for (auto it = vd.vertices_begin(); it != vd.vertices_end(); ++it) {
    std::vector<cg3::Point2d> cell;
    cg3::cgal::internal::Ccb_halfedge_circulator ec = it->incident_halfedges();
    do {
        cg3::cgal::internal::Halfedge_handle he = ec;
        if (he->has_source()) {
            const auto& p = he->source()->point();
            cell.push_back(cg3::Point2d(p.x(), p.y()));
        }
        ++ec;
    } while (ec != it->incident_halfedges());
    result.push_back(cell);
}
return result;

